import{_ as e,o as t,c as r,a4 as s}from"./chunks/framework.BUqnS5H7.js";const f=JSON.parse('{"title":"消费者组","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/02-core/chapter-03-consumer-group.md","filePath":"kafka/02-core/chapter-03-consumer-group.md"}'),o={name:"kafka/02-core/chapter-03-consumer-group.md"};function n(c,a,l,i,p,d){return t(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="消费者组" tabindex="-1" data-src-line="1" data-src-file="kafka/02-core/chapter-03-consumer-group.md">消费者组 <a class="header-anchor" href="#消费者组" aria-label="Permalink to &quot;消费者组&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><p data-src-line="3" data-src-file="kafka/02-core/chapter-03-consumer-group.md">消费者组不是一个&quot;功能&quot;，而是 Kafka 在&quot;多个消费者怎么协作消费同一个 Topic&quot;这个问题上给出的答案。理解它的关键在于：为什么一个分区只能被组内一个消费者消费？Rebalance 是什么，为什么不可避免？</p></blockquote><h2 id="_1-从两个基本需求开始" tabindex="-1" data-src-line="5" data-src-file="kafka/02-core/chapter-03-consumer-group.md">1. 从两个基本需求开始 <a class="header-anchor" href="#_1-从两个基本需求开始" aria-label="Permalink to &quot;1. 从两个基本需求开始&quot;">​</a></h2><p data-src-line="7" data-src-file="kafka/02-core/chapter-03-consumer-group.md">假设你有一个 Topic 有 3 个分区，消息量很大，一个消费者处理不过来。你需要多个消费者并行消费。</p><p data-src-line="9" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>需求一：并行消费</strong>。3 个消费者，每个消费一个分区，速度变 3 倍。</p><p data-src-line="11" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>需求二：不重复消费</strong>。同一条消息不能被两个消费者同时处理——否则下游系统会收到重复数据。</p><p data-src-line="13" data-src-file="kafka/02-core/chapter-03-consumer-group.md">这两个需求之间有矛盾。如果 3 个消费者各自独立消费所有 3 个分区，那就是 3 倍的重复处理。如果要避免重复，就必须有一个规则：<strong>每个分区只分配给一个消费者</strong>。</p><p data-src-line="15" data-src-file="kafka/02-core/chapter-03-consumer-group.md">消费者组就是这个规则的实现。</p><h2 id="_2-消费者组模型" tabindex="-1" data-src-line="17" data-src-file="kafka/02-core/chapter-03-consumer-group.md">2. 消费者组模型 <a class="header-anchor" href="#_2-消费者组模型" aria-label="Permalink to &quot;2. 消费者组模型&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Topic 有 3 个分区</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Consumer Group A（2 个消费者）：</span></span>
<span class="line"><span>  Consumer A1 → Partition 0, Partition 1</span></span>
<span class="line"><span>  Consumer A2 → Partition 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Consumer Group B（3 个消费者）：</span></span>
<span class="line"><span>  Consumer B1 → Partition 0</span></span>
<span class="line"><span>  Consumer B2 → Partition 1</span></span>
<span class="line"><span>  Consumer B3 → Partition 2</span></span></code></pre></div><p data-src-line="32" data-src-file="kafka/02-core/chapter-03-consumer-group.md">核心规则：</p><ul data-src-line="34" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><li data-src-line="34" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>一个分区只能被组内一个消费者消费</strong>：保证组内不重复消费</li><li data-src-line="35" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>一个消费者可以消费多个分区</strong>：分区数 &gt; 消费者数时</li><li data-src-line="36" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>消费者数 &gt; 分区数</strong>：多余的消费者空闲，浪费资源</li><li data-src-line="37" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>不同组独立消费</strong>：Group A 和 Group B 各自维护自己的 Offset，互不影响</li></ul><p data-src-line="39" data-src-file="kafka/02-core/chapter-03-consumer-group.md">最后一条是 Kafka 天然支持&quot;发布/订阅&quot;的原因：同一个 Topic 可以被多个消费者组独立消费，每个组看到的是完整的消息流。</p><h2 id="_3-为什么分区数是并行度的天花板" tabindex="-1" data-src-line="41" data-src-file="kafka/02-core/chapter-03-consumer-group.md">3. 为什么分区数是并行度的天花板 <a class="header-anchor" href="#_3-为什么分区数是并行度的天花板" aria-label="Permalink to &quot;3. 为什么分区数是并行度的天花板&quot;">​</a></h2><p data-src-line="43" data-src-file="kafka/02-core/chapter-03-consumer-group.md">这个结论直接来自&quot;一个分区只能被组内一个消费者消费&quot;的规则：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Topic 有 3 个分区，消费者组有 5 个消费者</span></span>
<span class="line"><span></span></span>
<span class="line"><span>分配结果：</span></span>
<span class="line"><span>  Consumer 1 → Partition 0</span></span>
<span class="line"><span>  Consumer 2 → Partition 1</span></span>
<span class="line"><span>  Consumer 3 → Partition 2</span></span>
<span class="line"><span>  Consumer 4 → （空闲）</span></span>
<span class="line"><span>  Consumer 5 → （空闲）</span></span></code></pre></div><p data-src-line="56" data-src-file="kafka/02-core/chapter-03-consumer-group.md">多出来的消费者无事可做。所以分区数决定了消费并行度的上限——不是消费者数，不是 Broker 数，而是分区数。</p><p data-src-line="58" data-src-file="kafka/02-core/chapter-03-consumer-group.md">这意味着：如果你的消费者处理速度跟不上生产速度，增加消费者实例的前提是分区数足够多。否则你加再多消费者也没用。</p><h2 id="rebalance" tabindex="-1" data-src-line="60" data-src-file="kafka/02-core/chapter-03-consumer-group.md">4. Rebalance：为什么不可避免 <a class="header-anchor" href="#rebalance" aria-label="Permalink to &quot;4. Rebalance：为什么不可避免 {#rebalance}&quot;">​</a></h2><p data-src-line="62" data-src-file="kafka/02-core/chapter-03-consumer-group.md">消费者组不是静态的。消费者会加入、离开、宕机。每次组成员变化，分区分配方案就必须重新计算——这就是 <strong>Rebalance</strong>。</p><p data-src-line="64" data-src-file="kafka/02-core/chapter-03-consumer-group.md">触发 Rebalance 的场景：</p><table tabindex="0"><thead data-src-line="66" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><tr data-src-line="66" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><th style="text-align:left;">场景</th><th style="text-align:left;">为什么会触发</th></tr></thead><tbody data-src-line="68" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><tr data-src-line="68" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;">新消费者加入</td><td style="text-align:left;">多了一个消费者，需要重新分配分区</td></tr><tr data-src-line="69" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;">消费者离开（主动退出）</td><td style="text-align:left;">少了一个消费者，它负责的分区需要分配给别人</td></tr><tr data-src-line="70" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;">消费者被踢出（心跳超时）</td><td style="text-align:left;">Coordinator 认为消费者已死，触发 Rebalance</td></tr><tr data-src-line="71" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;">消费者被踢出（poll 超时）</td><td style="text-align:left;">消费者处理消息太久没调用 poll()，被认为已死</td></tr><tr data-src-line="72" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;">Topic 分区数增加</td><td style="text-align:left;">多了新分区，需要分配给消费者</td></tr></tbody></table><h3 id="rebalance-flow" tabindex="-1" data-src-line="74" data-src-file="kafka/02-core/chapter-03-consumer-group.md">4.1 Rebalance 期间发生了什么 <a class="header-anchor" href="#rebalance-flow" aria-label="Permalink to &quot;4.1 Rebalance 期间发生了什么 {#rebalance-flow}&quot;">​</a></h3><p data-src-line="76" data-src-file="kafka/02-core/chapter-03-consumer-group.md">上面描述的是 <strong>Eager（急切式）Rebalance</strong>，也是 Kafka 长期以来的默认行为，流程是&quot;全停 → 重新分配 → 恢复&quot;：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 某个消费者离开，向 Coordinator 发送 LeaveGroup</span></span>
<span class="line"><span>2. Coordinator 通知组内所有消费者：&quot;停止消费，准备 Rebalance&quot;</span></span>
<span class="line"><span>3. 所有消费者发送 JoinGroup，报告自己订阅了哪些 Topic</span></span>
<span class="line"><span>4. Coordinator 选出 Group Leader（第一个加入的消费者）</span></span>
<span class="line"><span>5. Group Leader 根据分配策略计算分区分配方案</span></span>
<span class="line"><span>6. Group Leader 把方案发给 Coordinator</span></span>
<span class="line"><span>7. Coordinator 把每个消费者的分配方案分发给对应消费者</span></span>
<span class="line"><span>8. 每个消费者知道自己的分区，恢复消费</span></span></code></pre></div><p data-src-line="89" data-src-file="kafka/02-core/chapter-03-consumer-group.md">Eager 模式下，Rebalance 期间<strong>所有消费者停止消费</strong>。这不是 bug，而是有意为之——如果在重新分配过程中允许消费，可能出现同一个分区被两个消费者同时消费的窗口。</p><p data-src-line="91" data-src-file="kafka/02-core/chapter-03-consumer-group.md">但&quot;全停&quot;不是唯一选择。Eager 的代价是：哪怕只有一个分区需要迁移，整个组的消费也会整体停顿一次。Kafka 2.4 起（<a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-429" target="_blank" rel="noreferrer">KIP-429</a>）引入 <strong>Cooperative（协作式）Rebalance</strong>，把重分配拆成多轮，只暂停真正需要迁移的分区，其余分区照常消费。它由 <code>CooperativeStickyAssignor</code> 承载，Kafka 3.0 起成为默认分配策略。两者的取舍见 <a href="#assignor">§5 分配策略</a>。</p><h2 id="assignor" tabindex="-1" data-src-line="93" data-src-file="kafka/02-core/chapter-03-consumer-group.md">5. 分配策略 <a class="header-anchor" href="#assignor" aria-label="Permalink to &quot;5. 分配策略 {#assignor}&quot;">​</a></h2><p data-src-line="95" data-src-file="kafka/02-core/chapter-03-consumer-group.md">Kafka 提供了四种分配策略，它们的核心区别在于&quot;Rebalance 时要不要尽量保持原有分配&quot;：</p><p data-src-line="97" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>Range</strong>：按分区编号范围分配。简单，但多 Topic 时可能不均衡——同一个消费者可能分到多个 Topic 的前半段。</p><p data-src-line="99" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>RoundRobin</strong>：把所有 Topic 的分区放在一起轮询。更均衡，但 Rebalance 时可能打乱大量原有分配。</p><p data-src-line="101" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>Sticky</strong>：在 RoundRobin 基础上增加&quot;尽量保持原分配&quot;的约束。Rebalance 时只迁移必要的分区。</p><p data-src-line="103" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>CooperativeSticky</strong>（推荐）：在 Sticky 基础上改用&quot;协作式&quot;Rebalance——不是所有消费者同时停止，而是只暂停被迁移的分区，其他分区继续消费。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统 Rebalance（Stop-the-World）：</span></span>
<span class="line"><span>  所有分区暂停 → 重新分配 → 恢复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CooperativeSticky（逐步迁移）：</span></span>
<span class="line"><span>  第1轮：识别需要迁移的分区，通知原消费者释放</span></span>
<span class="line"><span>  第2轮：新消费者获取迁移的分区，其他分区不受影响</span></span></code></pre></div><h3 id="_5-1-选型与版本" tabindex="-1" data-src-line="114" data-src-file="kafka/02-core/chapter-03-consumer-group.md">5.1 选型与版本 <a class="header-anchor" href="#_5-1-选型与版本" aria-label="Permalink to &quot;5.1 选型与版本&quot;">​</a></h3><p data-src-line="116" data-src-file="kafka/02-core/chapter-03-consumer-group.md">四种策略的引入版本与 Rebalance 协议：</p><table tabindex="0"><thead data-src-line="118" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><tr data-src-line="118" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><th style="text-align:left;">策略</th><th style="text-align:left;">引入版本</th><th style="text-align:left;">Rebalance 协议</th><th style="text-align:left;">依据</th></tr></thead><tbody data-src-line="120" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><tr data-src-line="120" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;"><code>RangeAssignor</code></td><td style="text-align:left;">早期（长期默认）</td><td style="text-align:left;">Eager</td><td style="text-align:left;">3.0 前的默认值</td></tr><tr data-src-line="121" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;"><code>RoundRobinAssignor</code></td><td style="text-align:left;">早期</td><td style="text-align:left;">Eager</td><td style="text-align:left;">与 Range 同属最早两种</td></tr><tr data-src-line="122" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;"><code>StickyAssignor</code></td><td style="text-align:left;">0.11.0.0（2017）</td><td style="text-align:left;">Eager</td><td style="text-align:left;"><a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-54" target="_blank" rel="noreferrer">KIP-54</a></td></tr><tr data-src-line="123" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;"><code>CooperativeStickyAssignor</code></td><td style="text-align:left;">2.4.0（2019）</td><td style="text-align:left;">Eager / Cooperative</td><td style="text-align:left;"><a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-429" target="_blank" rel="noreferrer">KIP-429</a></td></tr><tr data-src-line="124" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><td style="text-align:left;">默认改为 <code>CooperativeSticky</code></td><td style="text-align:left;">3.0（2021）</td><td style="text-align:left;">Cooperative</td><td style="text-align:left;"><a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-726" target="_blank" rel="noreferrer">KIP-726</a></td></tr></tbody></table><p data-src-line="126" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>生产环境选型</strong>：Kafka 3.0 起默认即 <code>CooperativeStickyAssignor</code>，无需配置。Kafka 2.4 起同样可用，显式配置即可：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">props.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ConsumerConfig.PARTITION_ASSIGNMENT_STRATEGY_CONFIG,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          CooperativeStickyAssignor.class.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">版本差异</p><ul data-src-line="135" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><li data-src-line="135" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>2.4+ 可用</strong>：<code>CooperativeStickyAssignor</code> 自 2.4.0 引入，2.4 及以后的 2.x 都能用，显式配置即生效，与 3.0 行为等价。</li><li data-src-line="136" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>3.0+ 新集群</strong>：默认已是 CooperativeSticky，无需配置，直接受益。</li><li data-src-line="137" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>存量老集群迁移</strong>：已在运行的老消费者组要从 <code>Range/RoundRobin/Sticky</code> 迁到 Cooperative，必须走 <a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-429" target="_blank" rel="noreferrer">KIP-429</a> 的两步滚动升级——第一次滚动把 <code>CooperativeStickyAssignor</code> 加到策略列表末尾（此时仍走 Eager），第二次滚动再移除旧的 <code>Range/RoundRobin/Sticky</code>。不能一步到位，否则组内新旧消费者混用 Eager / Cooperative 协议，同一分区可能被两个消费者同时认领、都提交 offset。</li><li data-src-line="138" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>组内配置必须一致</strong>：<code>partition.assignment.strategy</code> 是组级协商出来的，只要组内有一个消费者不支持 Cooperative，整组退回 Eager。</li></ul></div><h2 id="_6-心跳与-poll-两个超时的含义" tabindex="-1" data-src-line="141" data-src-file="kafka/02-core/chapter-03-consumer-group.md">6. 心跳与 poll：两个超时的含义 <a class="header-anchor" href="#_6-心跳与-poll-两个超时的含义" aria-label="Permalink to &quot;6. 心跳与 poll：两个超时的含义&quot;">​</a></h2><p data-src-line="143" data-src-file="kafka/02-core/chapter-03-consumer-group.md">消费者需要定期向 Coordinator 报告&quot;我还活着&quot;。有两个超时参数，它们检测的是不同的问题：</p><p data-src-line="145" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong><code>session.timeout.ms</code></strong>：心跳超时。消费者必须在 <code>heartbeat.interval.ms</code> 内发送心跳。如果超过 <code>session.timeout.ms</code> 没有心跳，Coordinator 认为消费者已死。</p><p data-src-line="147" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong><code>max.poll.interval.ms</code></strong>：poll 间隔超时。消费者必须在两次 <code>poll()</code> 调用之间不超过这个时间。如果处理消息太久没调用 <code>poll()</code>，Coordinator 认为消费者&quot;卡住了&quot;。</p><p data-src-line="149" data-src-file="kafka/02-core/chapter-03-consumer-group.md">两个超时的区别在于：<code>session.timeout.ms</code> 检测的是&quot;消费者进程是否还活着&quot;（网络分区、进程崩溃），<code>max.poll.interval.ms</code> 检测的是&quot;消费者是否还在正常消费&quot;（处理逻辑阻塞、死锁）。</p><h2 id="offset-management" tabindex="-1" data-src-line="151" data-src-file="kafka/02-core/chapter-03-consumer-group.md">7. Offset 管理 <a class="header-anchor" href="#offset-management" aria-label="Permalink to &quot;7. Offset 管理 {#offset-management}&quot;">​</a></h2><p data-src-line="153" data-src-file="kafka/02-core/chapter-03-consumer-group.md">消费者组的 Offset 是整个消费模型的&quot;进度条&quot;。它回答的问题是：&quot;这个消费者组消费到了哪里？&quot;</p><h3 id="_7-1-自动提交-vs-手动提交" tabindex="-1" data-src-line="155" data-src-file="kafka/02-core/chapter-03-consumer-group.md">7.1 自动提交 vs 手动提交 <a class="header-anchor" href="#_7-1-自动提交-vs-手动提交" aria-label="Permalink to &quot;7.1 自动提交 vs 手动提交&quot;">​</a></h3><p data-src-line="157" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>自动提交</strong>（<code>enable.auto.commit=true</code>）：消费者每隔 <code>auto.commit.interval.ms</code> 自动提交当前 Offset。问题在于：如果消息已经 poll 回来但还没处理完，Offset 已经提交了。此时消费者宕机，重启后从新 Offset 开始，那些未处理的消息就丢了。</p><p data-src-line="159" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><strong>手动提交</strong>（<code>enable.auto.commit=false</code>）：你控制什么时候提交 Offset。正确做法是处理完消息后再提交。但这里也有陷阱：如果你逐条处理逐条提交，性能极差；如果你等一批全部处理完再提交，处理过程中宕机，这批消息会被重新消费。</p><p data-src-line="161" data-src-file="kafka/02-core/chapter-03-consumer-group.md">这就是为什么 Kafka 的消费端天然支持&quot;At Least Once&quot;——消息可能被重复消费，但不会丢失。要实现 Exactly Once，需要在业务层做幂等处理。</p><h3 id="_7-2-offset-存在哪里" tabindex="-1" data-src-line="163" data-src-file="kafka/02-core/chapter-03-consumer-group.md">7.2 Offset 存在哪里 <a class="header-anchor" href="#_7-2-offset-存在哪里" aria-label="Permalink to &quot;7.2 Offset 存在哪里&quot;">​</a></h3><p data-src-line="165" data-src-file="kafka/02-core/chapter-03-consumer-group.md">Offset 存储在 <code>__consumer_offsets</code> 这个内部 Topic 中。Key 是 <code>(group.id, topic, partition)</code>，Value 是 Offset。选择存 Topic 而不是内存或外部存储，是因为 Topic 本身就有副本和持久化——Offset 不会因为单点故障丢失。</p><h2 id="static-membership" tabindex="-1" data-src-line="167" data-src-file="kafka/02-core/chapter-03-consumer-group.md">8. 静态成员 <a class="header-anchor" href="#static-membership" aria-label="Permalink to &quot;8. 静态成员 {#static-membership}&quot;">​</a></h2><p data-src-line="169" data-src-file="kafka/02-core/chapter-03-consumer-group.md">传统消费者组中，消费者重启就会向 Group Coordinator（Broker）申请新的 <code>member.id</code> ，加入群组会触发 Rebalance。但在滚动部署场景下，你希望重启一个消费者不影响其他消费者。</p><p data-src-line="171" data-src-file="kafka/02-core/chapter-03-consumer-group.md">静态成员（<code>group.instance.id</code>）解决了这个问题：消费者指定一个固定的 ID，重启后 Coordinator 用 ID 识别它是&quot;同一个消费者&quot;，只要在 <code>session.timeout.ms</code> 内重新连接就不触发 Rebalance。</p><h2 id="_9-lag-监控" tabindex="-1" data-src-line="173" data-src-file="kafka/02-core/chapter-03-consumer-group.md">9. Lag 监控 <a class="header-anchor" href="#_9-lag-监控" aria-label="Permalink to &quot;9. Lag 监控&quot;">​</a></h2><p data-src-line="175" data-src-file="kafka/02-core/chapter-03-consumer-group.md">Lag = 最新 Offset - 已提交 Offset。它告诉你&quot;消费者落后生产者多少条消息&quot;。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kafka-consumer-groups.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --describe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-group</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GROUP    TOPIC    PARTITION  CURRENT-OFFSET  LOG-END-OFFSET  LAG</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># my-group my-topic 0          1000            1500            500</span></span></code></pre></div><p data-src-line="183" data-src-file="kafka/02-core/chapter-03-consumer-group.md">Lag 稳定不增长 → 消费速度跟得上。Lag 持续增长 → 消费者处理能力不足，需要优化或扩容。</p><p data-src-line="185" data-src-file="kafka/02-core/chapter-03-consumer-group.md">Lag 过大的排查见 <a href="./../05-troubleshooting/chapter-01-consumer-lag.html">消费者 Lag 过大</a>。</p><h2 id="_10-一句话总结" tabindex="-1" data-src-line="187" data-src-file="kafka/02-core/chapter-03-consumer-group.md">10. 一句话总结 <a class="header-anchor" href="#_10-一句话总结" aria-label="Permalink to &quot;10. 一句话总结&quot;">​</a></h2><ul data-src-line="189" data-src-file="kafka/02-core/chapter-03-consumer-group.md"><li data-src-line="189" data-src-file="kafka/02-core/chapter-03-consumer-group.md">消费者组通过&quot;一个分区只分配给一个消费者&quot;的规则，在并行消费和不重复消费之间找到了平衡。</li><li data-src-line="190" data-src-file="kafka/02-core/chapter-03-consumer-group.md">Rebalance 是消费者组的动态适应机制——组成员变化时重新计算分配方案，代价是消费暂停。</li><li data-src-line="191" data-src-file="kafka/02-core/chapter-03-consumer-group.md">分区数是消费并行度的天花板，Offset 是消费进度的&quot;进度条&quot;。</li></ul>`,63)])])}const h=e(o,[["render",n]]);export{f as __pageData,h as default};
